{"file_text": "@page "/settings"
@rendermode InteractiveServer
@using sv_f00cbcecfaf5442ba6c754c61743e8fc.Models
@using sv_f00cbcecfaf5442ba6c754c61743e8fc.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar" aria-label="Settings sections">
        @foreach (var section in _sections)
        {
            <button class="settings-nav-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => SetActiveSection(section.Key)">
                <span class="settings-nav-icon">@section.Value.Icon</span>
                <span>@section.Value.Label</span>
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="settings-loading">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    <SettingsProfile Profile="_profile"
                                     SavedProfile="_savedProfile"
                                     OnSave="SaveProfileAsync"
                                     OnDiscard="DiscardProfileChanges" />
                    break;

                case "notifications":
                    <SettingsNotifications Prefs="_notificationPrefs"
                                           AllChannels="_allChannels"
                                           OnSave="SaveNotificationsAsync" />
                    break;

                case "security":
                    <SettingsSecurity Security="_security"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnRevokeSession="RevokeSessionAsync" />
                    break;

                case "appearance":
                    <SettingsAppearance Settings="_appearance"
                                        OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </div>
</div>

@if (_toastMessage is not null)
{
    <div class="settings-toast @(_toastIsError ? "error" : "")">
        @_toastMessage
    </div>
}

@code {
    private record SectionMeta(string Label, string Icon);

    private readonly Dictionary<string, SectionMeta> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨"),
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Data
    private UserProfile _profile = null!;
    private UserProfile _savedProfile = null!;
    private NotificationPrefs _notificationPrefs = null!;
    private List<string> _allChannels = InMemorySettingsService.AllChannels;
    private SecuritySettings _security = null!;
    private AppearanceSettings _appearance = null!;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllDataAsync();
        _loading = false;
    }

    private async Task LoadAllDataAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _savedProfile = _profile;
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _security = await SettingsService.GetSecuritySettingsAsync();
        _appearance = await SettingsService.GetAppearanceAsync();
    }

    private void SetActiveSection(string section)
    {
        ActiveSection = section;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
        _savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        _profile = _savedProfile;
        ShowToast("Changes discarded.");
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        ShowToast("Notification preferences saved!");
    }

    private async Task ChangePasswordAsync((string current, string newPw) pw)
    {
        await SettingsService.ChangePasswordAsync(pw.current, pw.newPw);
        _security = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!");
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked.");
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
        ShowToast("Appearance settings saved!");
    }

    private async void ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }
}
