.sessions-table tr:hover {
    background: #f8f9fa;
}

.current-session-badge {
    background: #d1e7dd;
    color: #0f5132;
    padding: 0.15rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.8rem;
    font-weight: 500;
}

/* Status indicator */
.status-indicator {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.25rem 0.75rem;
    border-radius: 1rem;
    font-size: 0.85rem;
    font-weight: 500;
}

.status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
}

.status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
}

.status-indicator.enabled .status-dot {
    background: #198754;
}

.status-indicator.disabled .status-dot {
    background: #dc3545;
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.5rem 0.75rem;
    background: #f8f9fa;
    border-radius: 0.375rem;
}

.channel-item label {
    margin: 0;
    font-weight: 400;
    cursor: pointer;
}

.channel-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    cursor: pointer;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 0;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    overflow: hidden;
    margin-top: 0.5rem;
}

.radio-option {
    flex: 1;
}

.radio-option input[type="radio"] {
    display: none;
}

.radio-option label {
    display: block;
    padding: 0.5rem 1rem;
    text-align: center;
    cursor: pointer;
    border-right: 1px solid #dee2e6;
    transition: all 0.15s;
    font-weight: 400;
    margin: 0;
}

.radio-option:last-child label {
    border-right: none;
}

.radio-option input[type="radio"]:checked + label {
    background: #0d6efd;
    color: #fff;
    font-weight: 500;
}

/* Live preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-top: 1.25rem;
    transition: all 0.3s ease;
}

.appearance-preview.theme-dark {
    background: #212529;
    color: #f8f9fa;
    border-color: #495057;
}

.appearance-preview.theme-light {
    background: #ffffff;
    color: #212529;
}

.appearance-preview.theme-system {
    background: linear-gradient(135deg, #fff 50%, #212529 50%);
    color: #212529;
}

.appearance-preview.font-small {
    font-size: 0.8rem;
}

.appearance-preview.font-medium {
    font-size: 1rem;
}

.appearance-preview.font-large {
    font-size: 1.2rem;
}

.appearance-preview.compact .preview-item {
    padding: 0.25rem 0;
}

.preview-item {
    padding: 0.5rem 0;
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
}

.preview-item:last-child {
    border-bottom: none;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

/* Confirmation dialog */
.confirm-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1040;
    animation: fade-in 0.15s;
}

.confirm-dialog {
    background: #fff;
    border-radius: 0.75rem;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
}

.confirm-dialog h4 {
    margin: 0 0 0.75rem;
}

.confirm-dialog p {
    color: #6c757d;
    margin-bottom: 1.25rem;
}

.confirm-dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

@keyframes fade-in {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* Validation error */
.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

/* Password info */
.password-info {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.5rem;
}
