@using sv_f00cbcecfaf5442ba6c754c61743e8fc.Models

<h2 class="settings-section-title">Notifications</h2>

<div class="settings-toggle">
    <div>
        <div class="settings-toggle-label">Email Notifications</div>
        <div class="settings-toggle-desc">Receive notifications via email</div>
    </div>
    <label class="toggle-switch">
        <input type="checkbox" @bind="_emailNotifications" />
        <span class="toggle-slider"></span>
    </label>
</div>

<div class="settings-toggle">
    <div>
        <div class="settings-toggle-label">Push Notifications</div>
        <div class="settings-toggle-desc">Receive push notifications in your browser</div>
    </div>
    <label class="toggle-switch">
        <input type="checkbox" @bind="_pushNotifications" />
        <span class="toggle-slider"></span>
    </label>
</div>

<div class="settings-toggle">
    <div>
        <div class="settings-toggle-label">Weekly Digest</div>
        <div class="settings-toggle-desc">Receive a weekly summary of activity</div>
    </div>
    <label class="toggle-switch">
        <input type="checkbox" @bind="_weeklyDigest" />
        <span class="toggle-slider"></span>
    </label>
</div>

<div class="settings-group" style="margin-top: 1.5rem;">
    <label>Muted Channels</label>
    <p style="font-size:0.85rem; color:#6c757d; margin-bottom:0.75rem;">
        Muted channels will not send you notifications.
    </p>
    <div class="channel-list">
        @foreach (var channel in AllChannels)
        {
            var ch = channel;
            <div class="channel-item">
                <input type="checkbox" id="ch-@ch"
                       checked="@_mutedChannels.Contains(ch)"
                       @onchange="(e) => ToggleChannel(ch, (bool)(e.Value ?? false))" />
                <label for="ch-@ch">#@ch</label>
            </div>
        }
    </div>
</div>

<div class="settings-btn-group">
    <button class="settings-btn settings-btn-primary" @onclick="HandleSave">
        Save Preferences
    </button>
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = null!;
    [Parameter, EditorRequired] public List<string> AllChannels { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = [];

    protected override void OnParametersSet()
    {
        _emailNotifications = Prefs.EmailNotifications;
        _pushNotifications = Prefs.PushNotifications;
        _weeklyDigest = Prefs.WeeklyDigest;
        _mutedChannels = [.. Prefs.MutedChannels];
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task HandleSave()
    {
        var updated = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
    }
}

@using sv_f00cbcecfaf5442ba6c754c61743e8fc.Models

<h2 class="settings-section-title">Security</h2>

<!-- Change Password -->
<div class="expandable-panel">
    <button class="expandable-panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
        <span>Change Password</span>
        <span class="expand-icon @(_passwordPanelOpen ? "open" : "")">▼</span>
    </button>
    @if (_passwordPanelOpen)
    {
        <div class="expandable-panel-body">
            <div class="settings-group">
                <label for="currentPw">Current Password</label>
                <input type="password" id="currentPw" @bind="_currentPassword" />
            </div>
            <div class="settings-group">
                <label for="newPw">New Password</label>
                <input type="password" id="newPw" @bind="_newPassword" />
            </div>
            <div class="settings-group">
                <label for="confirmPw">Confirm New Password</label>
                <input type="password" id="confirmPw" @bind="_confirmPassword" />
            </div>
            @if (_passwordError is not null)
            {
                <div class="field-error">@_passwordError</div>
            }
            @if (Security.LastPasswordChange.HasValue)
            {
                <div class="password-info">
                    Last changed: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </div>
            }
            <div class="settings-btn-group">
                <button class="settings-btn settings-btn-primary" @onclick="HandleChangePassword">
                    Update Password
                </button>
            </div>
        </div>
    }
</div>

<!-- Two-Factor Authentication -->
<div class="settings-toggle" style="margin-bottom: 1.5rem;">
    <div>
        <div class="settings-toggle-label">Two-Factor Authentication</div>
        <div class="settings-toggle-desc">Add an extra layer of security to your account</div>
    </div>
    <div style="display: flex; align-items: center; gap: 1rem;">
        <span class="status-indicator @(Security.TwoFactorEnabled ? "enabled" : "disabled")">
            <span class="status-dot"></span>
            @(Security.TwoFactorEnabled ? "Enabled" : "Disabled")
        </span>
        <label class="toggle-switch">
            <input type="checkbox" checked="@Security.TwoFactorEnabled" disabled />
            <span class="toggle-slider"></span>
        </label>
    </div>
</div>

<!-- Active Sessions -->
<h3 style="font-size: 1.1rem; font-weight: 600; margin-bottom: 1rem;">Active Sessions</h3>
<table class="sessions-table">
    <thead>
        <tr>
            <th>Device</th>
            <th>Location</th>
            <th>Last Active</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var session in Security.Sessions)
        {
            <tr>
                <td>
                    @session.Device
                    @if (session.Id == "current")
                    {
                        <span class="current-session-badge" style="margin-left:0.5rem;">Current</span>
                    }
                </td>
                <td>@session.Location</td>
                <td>@FormatLastActive(session.LastActive)</td>
                <td>
                    @if (session.Id != "current")
                    {
                        <button class="settings-btn settings-btn-danger settings-btn-sm"
                                @onclick="() => PromptRevokeSession(session)">
                            Revoke
                        </button>
                    }
                </td>
            </tr>
        }
    </tbody>
</table>

<!-- Confirm Dialog -->
@if (_sessionToRevoke is not null)
{
    <div class="confirm-overlay" @onclick="CancelRevoke">
        <div class="confirm-dialog" @onclick:stopPropagation="true">
            <h4>Revoke Session</h4>
            <p>
                Are you sure you want to revoke the session on
                <strong>@_sessionToRevoke.Device</strong> from
                <strong>@_sessionToRevoke.Location</strong>?
                This will sign out that device.
            </p>
            <div class="confirm-dialog-actions">
                <button class="settings-btn settings-btn-secondary" @onclick="CancelRevoke">
                    Cancel
                </button>
                <button class="settings-btn settings-btn-danger" @onclick="ConfirmRevoke">
                    Revoke
                </button>
            </div>
        </div>
    </div>
}

